code.C:
#include <stdio.h>
#include <string.h>
#include <ctype.h>
int main() {
    char s[100000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    char filtered[100000]; int len = 0;
    for (int i = 0; s[i]; i++) if (isalnum(s[i])) filtered[len++] = tolower(s[i]);
    int is_pal = 1;
    for (int l = 0, r = len - 1; l < r; l++, r--) {
        if (filtered[l] != filtered[r]) { is_pal = 0; break; }
    }
    puts(is_pal ? "true" : "false");
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <cctype>
using namespace std;
int main() {
    string s; if (!getline(cin, s)) return 0;
    string f = "";
    for (char c : s) if (isalnum(c)) f += tolower(c);
    bool pal = true;
    for (size_t l = 0, r = f.length() ? f.length() - 1 : 0; l < r; l++, r--) {
        if (f[l] != f[r]) { pal = false; break; }
    }
    cout << (pal ? "true" : "false") << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String s = sc.nextLine().replaceAll("[^a-zA-Z0-9]", "").toLowerCase();
            boolean pal = true;
            for (int l = 0, r = s.length() - 1; l < r; l++, r--) {
                if (s.charAt(l) != s.charAt(r)) { pal = false; break; }
            }
            System.out.println(pal ? "true" : "false");
        }
    }
}

